-- 093_seed_digests_t2t3.sql · 유형별 요약 뭉치 (T2 고액 환금성 실물자산 · T3 암호화폐)
-- 출처 : 092_seed_corpus_t2t3.sql
--
-- verified = true. T2 는 대법원 판결문 전문을, T3 는 상담사례 두 건 전문을 직접 읽고 대조했다.
--
-- 이 두 유형만의 특징 : 당사자 1인칭 서사가 없다. 그래서 '표현' 칸을
-- 커뮤니티 문장이 아니라 판결문 문구와 기관 안내문으로 채웠다.
-- 소명서에 그대로 인용할 수 있는 문장이라는 점에서는 오히려 더 강하다.

-- ══════════════ T2 · 고액 환금성 실물자산형 (금·귀금속·외화) ══════════════
INSERT INTO case_digests (document_id, case_type_id, section, body, verified, verified_on)
SELECT d.id, (SELECT id FROM case_types WHERE code='T2'), s.section, s.body, true, '2026-09-06'
FROM corpus_documents d, (VALUES
('상황',
 '중고거래 사이트에 100돈짜리 순금 목걸이를 2,900만원에 판다고 올렸다. 구매자를 만난 자리에서 제3자 명의로 예약금 3만원이 계좌에 들어왔고, 다음 날 다시 만나 나머지 2,895만원이 같은 제3자 명의로 입금된 것을 확인한 뒤 목걸이를 건넸다. 그 돈은 딸을 사칭한 보이스피싱범에게 속아 휴대폰에 원격제어 프로그램을 설치한 피해자의 계좌에서, 범죄자가 그 프로그램으로 직접 빼내 이체한 것이었다. 목걸이를 받아간 사람은 수거책이었고 나중에 유죄가 확정됐다. 피해자는 판매자를 상대로 부당이득 반환 소송을 냈다. 금융감독원 접수 민원 기준으로 이 수법은 2025년 10월 1건에서 11월 13건, 12월 9건, 2026년 1월 11건으로 늘고 있다.'),
('쟁점',
 '판매자가 받은 돈에 법률상 원인이 있는지가 쟁점이었다. 입금자명이 거래 상대와 달랐는데 그 사실만으로 판매자에게 중대한 과실이 있다고 볼 수 있는지, 그리고 피해자가 스스로 이체하지 않고 범죄자가 원격제어로 빼간 경우를 다르게 취급해야 하는지가 함께 다투어졌다. 원심은 판매자와 피해자 사이에 이체의 원인이 되는 법률관계가 없다는 이유로 판매자에게 반환 의무가 있다고 봤다.'),
('인정된것',
 '대법원 2024. 6. 27. 선고 2024다216187 판결이 원심을 파기하고 판매자 손을 들어줬다. 편취한 금전을 채무 변제에 쓴 경우, 그 변제를 받은 채권자에게 편취 사실에 대한 악의나 중대한 과실이 없다면 그 취득은 피해자에 대한 관계에서도 법률상 원인이 있다는 것이다. 여기서 중대한 과실이란 조금만 주의를 기울였다면 편취금이라는 사실을 쉽게 알 수 있었는데도 그러지 않은, 일반인에게 요구되는 주의의무를 현저히 위반한 경우를 말한다. 가장 중요한 것은 증명책임의 소재다. 판매자가 몰랐음을 입증하는 것이 아니라, 피해자 측이 판매자의 악의나 중대한 과실을 증명해야 한다. 대법원은 판매자가 중고거래 사이트를 통해 목걸이를 판매했을 뿐이므로 편취금인 줄 알았거나 모른 데 중대한 과실이 있다고 단정하기 어렵다고 봤고, 피해자가 직접 이체했든 범죄자가 원격제어로 이체했든 달리 취급할 이유가 없다고 했다. 민사에서는 방어력이 매우 높은 유형이다.'),
('기각된것',
 '이 판결은 민사 부당이득 다툼이지 지급정지 이의제기가 아니다. 이겨도 계좌가 묶이는 것 자체를 막아주지는 못한다. 금융감독원은 이 유형에서 판매자 계좌가 통신사기피해환급법상 사기이용계좌로 지정되어 지급정지와 전자금융거래 제한을 받고 거래대금을 피해자에게 반환하는 불이익을 받을 수 있다고 안내한다. 증거 쪽 공백도 크다. 사기범이 거래 전후에 게시글을 내리거나 숨기라고 요구하는 것이 이 수법의 특징인데, 그 요구에 응하면 거래가 실재했다는 증거의 절반이 사라진다. 고액 대면 직거래인데 인도 증빙이 없는 것도 문제다. 판례에서도 목걸이를 실제로 건넸다는 사실은 수거책이 형사재판에서 유죄를 받으며 밝혀진 것이지 판매자가 미리 준비해 둔 증거로 입증된 것이 아니다. 소송을 당하고도 대응하지 않으면 원고 주장이 부당하더라도 그대로 인정되어 전부 패소한다.'),
('표현',
 '판결문에 그대로 쓰인 문장이라 소명서에 인용할 수 있다 — "채무자가 피해자로부터 편취한 금전을 자신의 채권자에 대한 채무변제에 사용하는 경우 채권자가 그 변제를 수령하면서 그 금전이 편취된 것이라는 사실에 대하여 악의 또는 중대한 과실이 없다면, 채권자의 금전취득은 피해자에 대한 관계에서 법률상 원인이 있는 것으로 봄이 타당하다". 그리고 "채권자가 수령한 금전이 편취된 것이라는 사실을 알았거나 중대한 과실로 알지 못하였다는 점에 대한 증명책임은 피해자에게 있다". 금융감독원이 정리한 이 수법의 신호도 함께 안내한다. 환금성 좋은 고액 자산을 표적으로 삼는다는 것, 미리 계좌번호를 받아 예약금을 먼저 이체한다는 것, 본인확인 요청에 비협조적이면서 거래 전후 게시글을 내려달라고 요구한다는 것이다. 게시글을 내려달라는 요구를 받았다면 그 대화 자체를 증거로 보존해야 한다.')
) AS s(section, body)
WHERE d.source_url = 'https://www.law.go.kr/precInfoP.do?precSeq=240967';

-- ══════════════ T3 · 암호화폐 매도형 ══════════════
INSERT INTO case_digests (document_id, case_type_id, section, body, verified, verified_on)
SELECT d.id, (SELECT id FROM case_types WHERE code='T3'), s.section, s.body, true, '2026-09-06'
FROM corpus_documents d, (VALUES
('상황',
 '개인 간 거래로 코인을 팔고 2,000만원을 입금받았는데 그 돈이 보이스피싱 피해금으로 드러나 계좌가 지급정지됐다. 판매자는 빚이 없다는 것을 확인받으려고 먼저 채무부존재 확인소송을 냈다. 이미 받은 돈 일부를 대출 상환에 써 버린 상태였다. 다른 사례에서는 테더 거래에 엮여 12건의 사건 중 9건이 내사종결되고 나머지도 전자금융거래법 위반과 사기방조 혐의로 모두 불기소됐는데, 피해자 한 명이 검사 출신 변호사를 선임해 이의를 제기하면서 6개월 넘는 재수사 끝에 사건이 검찰로 넘어갔고 전기통신사기 혐의로 출석 요구를 받았다.'),
('쟁점',
 '민사에서는 판매자가 받은 돈이 부당이득인지, 그리고 이미 써 버린 돈까지 물어내야 하는지가 쟁점이다. 형사에서는 코인 거래의 정당성과 사기 인식 여부가 쟁점이다. 이 유형의 특징은 트랙이 하나로 끝나지 않는다는 점이다. 무혐의를 받아도 피해자의 이의제기로 재수사가 열릴 수 있고, 형사와 민사가 동시에 진행되기도 한다.'),
('인정된것',
 '거래가 정당했음을 입증하면 이길 가능성이 높다. 법원은 물품 등을 팔고 대금을 받은 계좌 주인이 사기 사실을 전혀 몰랐다면 책임을 묻지 않는 경향이 있고, 대법원도 중고거래 사안에서 판매자가 범행을 몰랐다면 정당한 취득이라고 판시했다. 특히 채무부존재 확인소송에서는 증명책임이 판매자가 아니라 상대인 피해자에게 있다. 피해자 측이 판매자가 범행에 가담했거나 사기라는 사실을 알았거나 중대한 과실로 알지 못했다는 점을 증명해야 한다. 준비할 것은 코인 거래소 기록, 지갑 전송 내역, 거래 당시 대화 내용이다. 온체인 기록이 남는다는 점이 이 유형의 강점이다. 상대 답변서를 받았다면 반박 준비서면을 제출해야 한다.'),
('기각된것',
 '소송에서 지면 남아 있는 돈만이 아니라 받은 원금 전액을 물어내야 한다. 이미 대출 상환에 썼더라도 대출금이 줄어드는 이익을 얻었으므로 이익이 현존하는 것으로 보기 때문에 결론이 달라지지 않는다. 그리고 이겨야 계좌가 풀린다. 통신사기피해환급법상 소송이 계속 중일 때는 지급정지가 유지되므로, 확정판결을 받기 전까지는 계좌를 되살릴 방법이 없다. 온체인 기록이 남는다는 강점에도 공백이 있는데, 수취 지갑이 그 상대의 것임을 잇는 고리가 약하고 개인 간 장외거래 대화는 텔레그램 등에 흩어져 있어 삭제되기 쉽다. 무혐의로 끝났다고 안심할 수도 없다. 피해자가 이의를 제기하면 재수사가 열리고 검찰이 직접 조사에 나설 수 있다. 이때 수사관이 정식 조사 전에 자료 정리를 위해 미리 오라고 해도 변호인 없이 응해서는 안 된다. 그 자리에서 한 말이 진술로 남아 불리하게 쓰인다.'),
('표현',
 '이 유형에는 당사자 1인칭 서사가 없어 실무 조언의 공통분모를 옮긴다. 민사 방어의 핵심은 증명책임이 상대에게 있다는 점이며, 채무부존재 확인소송을 먼저 걸었다면 그 구조를 활용해야 한다. 준비서면에는 코인 거래소 기록과 지갑 전송 내역, 거래 당시 대화를 첨부해 정상적인 상거래였음을 보인다. 형사와 민사가 같이 굴러갈 때는 민사 소장을 받은 날부터 30일 안에 형사 방어 논리와 모순되지 않는 답변서를 먼저 내는 것이 좋다. 수사기관의 일정 재촉에 끌려가기보다 변호인 선임권과 방어권을 행사해 준비 시간을 확보하는 것이 낫다. 소송을 당하고 대응하지 않으면 상대 주장이 그대로 인정된다는 점은 이 유형에서도 같다.')
) AS s(section, body)
WHERE d.source_url = 'https://lawtalknews.co.kr/article/TRWRP6F11Y0F';
